/**
 * Bearer tokens and their stored hashes.
 *
 * A token is 32 random bytes, base64url — 256 bits, the same order as a UUIDv4
 * but not shaped like one, so it cannot be mistaken for an id in a log. It is
 * generated by `randomBytes`, which is the OS CSPRNG.
 *
 * **The stored value is a SHA-256 of the token, not scrypt.** That is deliberate:
 * a session token is already full-entropy random, so there is no dictionary to
 * slow an attacker down against, and a per-request scrypt would turn every API
 * call into a key derivation. A plain digest is the right trade here, and it is
 * still one-way — a database dump yields nothing a client can present.
 */

import { createHash, randomBytes } from 'node:crypto';

import type { TokenGenerator } from '@denti-code-u3/domain';

export class CryptoTokenGenerator implements TokenGenerator {
  nextToken(): string {
    return randomBytes(32).toString('base64url');
  }

  hashToken(token: string): string {
    return createHash('sha256').update(token).digest('hex');
  }
}
